from __future__ import annotations

from dataclasses import dataclass

import numpy as np


@dataclass(frozen=True)
class RobertsonModel:
    rate_slow: float
    rate_fast: float
    rate_return: float
    initial_composition: tuple[float, float, float]

    def rates(self, _time: float, composition: np.ndarray) -> np.ndarray:
        reactant, intermediate, product = composition
        return np.array(
            [
                -self.rate_slow * reactant
                + self.rate_return * intermediate * product,
                self.rate_slow * reactant
                - self.rate_return * intermediate * product
                - self.rate_fast * intermediate * intermediate,
                self.rate_fast * intermediate * intermediate,
            ]
        )

    def jacobian(self, _time: float, composition: np.ndarray) -> np.ndarray:
        _reactant, intermediate, product = composition
        return np.array(
            [
                [
                    -self.rate_slow,
                    self.rate_return * product,
                    self.rate_return * intermediate,
                ],
                [
                    self.rate_slow,
                    -self.rate_return * product
                    - 2.0 * self.rate_fast * intermediate,
                    -self.rate_return * intermediate,
                ],
                [0.0, 2.0 * self.rate_fast * intermediate, 0.0],
            ]
        )

