from __future__ import annotations

import sys
from dataclasses import dataclass
from pathlib import Path

import numpy as np

from .protocols import CampaignProtocol
from .solver_profiles import resolve_solver_profile


TASK_DIR = Path(__file__).resolve().parents[2]
SOURCE_DIR = TASK_DIR / "source"
if str(SOURCE_DIR) not in sys.path:
    sys.path.insert(0, str(SOURCE_DIR))

from scipy.integrate import solve_ivp


@dataclass(frozen=True)
class ProtocolObservation:
    protocol_id: str
    transition_time: float
    maximum_balance_residual: float
    sample_count: int


def run_protocol(protocol: CampaignProtocol) -> ProtocolObservation:
    solver_profile = resolve_solver_profile(protocol.solver_profile)

    def monitor(_time: float, composition: np.ndarray) -> float:
        return float(composition[0] - protocol.monitored_level)

    monitor.terminal = True
    initial_gap = float(
        protocol.model.initial_composition[0] - protocol.monitored_level
    )
    monitor.direction = -1 if initial_gap > 0.0 else 1

    time_horizon = protocol.time_horizon
    timeline = np.concatenate(
        (
            [0.0],
            np.geomspace(
                min(1.0e-6, time_horizon * 1.0e-3),
                time_horizon,
                protocol.sample_count,
            ),
        )
    )

    solver_kwargs = {
        "method": solver_profile.method,
        "rtol": protocol.relative_tolerance,
        "atol": np.asarray(protocol.absolute_tolerance),
        "t_eval": timeline,
        "events": monitor,
    }
    if solver_profile.use_analytic_jacobian:
        solver_kwargs["jac"] = protocol.model.jacobian

    result = solve_ivp(
        protocol.model.rates,
        (0.0, time_horizon),
        protocol.model.initial_composition,
        **solver_kwargs,
    )

    if not result.success or result.t_events[0].size != 1:
        raise RuntimeError("protocol did not produce one complete observation")
    if not np.all(np.isfinite(result.y)):
        raise RuntimeError("protocol produced a non-finite trajectory")

    conserved_total = float(np.sum(protocol.model.initial_composition))
    return ProtocolObservation(
        protocol_id=protocol.protocol_id,
        transition_time=float(result.t_events[0][0]),
        maximum_balance_residual=float(
            np.max(np.abs(np.sum(result.y, axis=0) - conserved_total))
        ),
        sample_count=int(result.y.shape[1]),
    )
